// 服务端状态归一化：嵌套结构 -> 实体表 + id 索引；再还原
const raw = { posts: [
  { id: 1, title: 'p1', author: { id: 9, name: 'ann' } },
  { id: 2, title: 'p2', author: { id: 9, name: 'ann' } },
  { id: 3, title: 'p3', author: { id: 7, name: 'bob' } },
] };

function normalize(data) {
  const entities = { posts: {}, users: {} };
  const result = [];
  for (const p of data.posts) {
    entities.posts[p.id] = { id: p.id, title: p.title, author: p.author.id };
    entities.users[p.author.id] = { id: p.author.id, name: p.author.name };
    result.push(p.id);
  }
  return { entities, result };
}
function denormalize(state, ids) {
  return ids.map(id => {
    const p = state.entities.posts[id];
    const u = state.entities.users[p.author];
    return { id: p.id, title: p.title, author: { id: u.id, name: u.name } };
  });
}

const norm = normalize(raw);
console.log('raw_author_objects=' + raw.posts.length);
console.log('normalized_user_count=' + Object.keys(norm.entities.users).length);
console.log('normalized_post_count=' + Object.keys(norm.entities.posts).length);
console.log('dedup_saved=' + (raw.posts.length - Object.keys(norm.entities.users).length));
console.log('result_ids=' + norm.result.join(','));
const round = denormalize(norm, norm.result);
console.log('roundtrip_equal=' + (JSON.stringify(round) === JSON.stringify(raw.posts)));
